// Convert the query point to CGAL point type
CGALPoint queryPoint(p.x(), p.y(), p.z());

// Query the tree for the nearest point
auto nearest = tree.closest_point_and_primitive(queryPoint);

// Extract the nearest point from the query result
CGALPoint nearestCgalPoint = nearest.first;

// Convert the CGAL point back to Point3d
return Point3d(
    std::round(nearestCgalPoint.x() * 1e10) / 1e10,  // Round to avoid floating point precision issues
    std::round(nearestCgalPoint.y() * 1e10) / 1e10,
    std::round(nearestCgalPoint.z() * 1e10) / 1e10
);

